package com.group01.assessment.application.usecase;
import com.group01.assessment.application.command.SaveAssessmentResultDetailsCommand; import com.group01.assessment.domain.exception.AssessmentNotFoundException; import com.group01.assessment.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class SaveAssessmentResultDetailsUseCase {private final AssessmentAttemptRepository attempts;private final AssessmentResultRepository results;private final SkillScoreRepository skills;private final ItemResultRepository items;private final ErrorAnalysisItemRepository errors;public SaveAssessmentResultDetailsUseCase(AssessmentAttemptRepository attempts,AssessmentResultRepository results,SkillScoreRepository skills,ItemResultRepository items,ErrorAnalysisItemRepository errors){this.attempts=attempts;this.results=results;this.skills=skills;this.items=items;this.errors=errors;}@Transactional public void execute(SaveAssessmentResultDetailsCommand c){attempts.findByIdAndUserId(c.attemptId(),c.userId()).orElseThrow(()->new AssessmentNotFoundException("Assessment attempt not found"));var result=results.findLatestByAttemptId(c.attemptId()).orElseThrow(()->new AssessmentNotFoundException("Assessment result not found"));if(c.skillScores()!=null&&!c.skillScores().isEmpty())skills.saveAll(c.skillScores().stream().map(s->new com.group01.assessment.domain.entity.SkillScore(s.id(),result.id(),s.skill(),s.rawScore(),s.band(),s.gradingSource(),s.feedbackRevisionId())).toList());if(c.itemResults()!=null&&!c.itemResults().isEmpty())items.saveAll(c.itemResults().stream().map(i->new com.group01.assessment.domain.entity.ItemResult(i.id(),result.id(),i.attemptItemId(),i.rawScore(),i.maxScore(),i.correct(),i.gradingSource())).toList());if(c.errors()!=null&&!c.errors().isEmpty())errors.saveAll(c.errors().stream().map(e->new com.group01.assessment.domain.entity.ErrorAnalysisItem(e.id(),result.id(),e.attemptItemId(),e.taxonomyCode(),e.severity(),e.note())).toList());}}
